module benchmark.owned.core;

@id("benchmark.owned.select")
fn select(view: borrow Slice<u8>, right: own Bytes, flag: usize, left: own Bytes) -> Bytes
{
    let observed = byte_len(view);
    if flag == observed { left } else { right }
}

@id("benchmark.owned.call")
fn call(input: borrow Slice<u8>) -> Bytes
{
    let left = bytes_copy(input);
    let right = bytes_copy(input);
    select(input, right, 0usize, left)
}

@id("benchmark.owned.consume")
fn consume(value: own Bytes) -> i64
{
    42
}

@id("benchmark.owned.evaluate")
fn evaluate(input: borrow Slice<u8>) -> i64
{
    consume(call(input))
}

@id("benchmark.owned.public")
fn public_value(value: i64) -> i64
{
    value
}

module benchmark.owned.app;
use function @id("benchmark.owned.evaluate") from benchmark.owned.core as evaluate;

@id("benchmark.owned.main")
fn main() -> i64
{
    let input = [1u8];
    evaluate(array_as_slice(input))
}

module benchmark.owned.tests;
use function @id("benchmark.owned.evaluate") from benchmark.owned.core as evaluate;

@id("benchmark.owned.test")
fn main() -> i64
{
    let input = [1u8];
    if evaluate(array_as_slice(input)) == 42 { 0 } else { 1 }
}
